SELECT * FROM template_info
AND ( template_info_name LIKE CONCAT('%', #{q.keyword}, '%') OR template_info_subtitle LIKE CONCAT('%', #{q.keyword}, '%') OR template_info_remark LIKE CONCAT('%', #{q.keyword}, '%') )
AND template_info_language = #{q.language}
AND template_info_type = #{q.type}
AND template_info_status = #{q.status}
AND template_info_deleted = 0
ORDER BY
template_info_name template_info_created_at template_info_updated_at
ASC DESC

SELECT *
FROM template_info


        AND template_info_name LIKE CONCAT('%', #{keyword}, '%')


        AND template_info_language = #{language}


        AND template_info_type = #{type}


        AND template_info_status = #{status}

    AND template_info_deleted = 0

ORDER BY template_info_updated_at DESC

SELECT COUNT(*)
FROM template_info


        AND template_info_name LIKE CONCAT('%', #{keyword}, '%')


        AND template_info_language = #{language}


        AND template_info_type = #{type}


        AND template_info_status = #{status}


        AND template_info_deleted = #{deleted}
